import json

def load(path):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.load_asset', json.dumps({'asset_path': path}))['returnValue']

def get(obj, names):
    return json.loads(execute_tool('editor_toolset.toolsets.object.ObjectTools.get_properties', json.dumps({'instance': obj, 'properties': names}))['returnValue'])

def dirty(path):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.is_dirty', json.dumps({'asset_path': path}))['returnValue']

def run():
    imc_path = '/ExtractionOps/Input/IMC_Extraction'
    addons_path = '/ExtractionOps/Input/DA_ExtractionInputAddOns'
    ability_set_path = '/ExtractionOps/AbilitySystem/AbilitySet_ExtractionCore'
    mappings = get(load(imc_path), ['defaultKeyMappings'])['defaultKeyMappings']['mappings']
    inventory_mappings = [m for m in mappings if 'IA_ExtractionInventory' in str(m.get('action'))]
    if len(inventory_mappings) != 1 or str(inventory_mappings[0].get('key')) != 'I':
        raise RuntimeError('inventory mapping mismatch: ' + str(inventory_mappings))
    actions = get(load(addons_path), ['abilityInputActions'])['abilityInputActions']
    input_actions = [a for a in actions if a.get('inputTag', {}).get('tagName') == 'InputTag.Ability.Inventory']
    if len(input_actions) != 1:
        raise RuntimeError('inventory input tag mismatch: ' + str(input_actions))
    grants = get(load(ability_set_path), ['grantedGameplayAbilities'])['grantedGameplayAbilities']
    ability_grants = [g for g in grants if 'ExtractionGameplayAbility_ToggleInventory' in str(g.get('ability'))]
    if len(ability_grants) != 1:
        raise RuntimeError('inventory ability grant mismatch: ' + str(ability_grants))
    paths = ['/ExtractionOps/Input/IA_ExtractionInventory', imc_path, addons_path, ability_set_path]
    dirty_paths = [p for p in paths if dirty(p)]
    if dirty_paths:
        raise RuntimeError('dirty inventory input assets: ' + str(dirty_paths))
    return {'mappingKey': 'I', 'inputActionCount': len(input_actions), 'abilityGrantCount': len(ability_grants), 'dirtyAssets': []}
